<?php declare(strict_types=1); ?>
<section class="recurring-task-view" data-recurring-task-view>
  <header class="recurring-task-heading"><div><span>Recurring definitions</span><h2>Recurring Tasks</h2><p>Manage the rules that generate future task occurrences. Historical tasks remain unchanged.</p></div><button class="dtb-btn dtb-btn-primary" type="button" data-task-create-open data-task-create-kind="recurring"><i data-lucide="plus"></i>Add Recurring Task</button></header>
  <div class="recurring-summary" aria-label="Recurring task summary">
    <?php foreach ([['Active recurring tasks','active','repeat-2'],['Paused','paused','pause'],['Next 24 hours','next_24_hours','clock-3'],['Missed / needs attention','attention','triangle-alert']] as [$label,$key,$icon]): ?>
      <article><i data-lucide="<?= $icon ?>" aria-hidden="true"></i><span><?= htmlspecialchars($label,ENT_QUOTES,'UTF-8') ?></span><strong><?= number_format((int)$recurringSummary[$key]) ?></strong></article>
    <?php endforeach; ?>
  </div>
  <form method="get" class="recurring-filters"><input type="hidden" name="task_view" value="recurring"><label><span>Search</span><input type="search" name="recurring_search" value="<?= htmlspecialchars((string)($_GET['recurring_search']??''),ENT_QUOTES,'UTF-8') ?>" placeholder="Search recurring tasks"></label><label><span>Status</span><select name="recurring_status"><option value="">All statuses</option><?php foreach(['active'=>'Active','paused'=>'Paused','ended'=>'Ended','cancelled'=>'Cancelled'] as $value=>$label): ?><option value="<?= $value ?>"<?= (string)($_GET['recurring_status']??'')===$value?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><button type="submit">Apply</button></form>
  <div class="recurring-table-wrap"><table class="recurring-task-table"><thead><tr><th>Task</th><th>Assignment</th><th>Repeat</th><th>Next Run</th><th>Last Run</th><th>Status</th><th>Generated</th><th>Actions</th></tr></thead><tbody>
  <?php if(!$recurringDefinitions): ?><tr><td colspan="8" class="recurring-empty">No recurring task definitions match this view.</td></tr><?php endif; ?>
  <?php foreach($recurringDefinitions as $definition): $id=(int)$definition['id'];$status=(string)($definition['status']??'active');$assignment=($definition['assignment_type']??'specific')==='floating'?'Floating · '.ucwords(str_replace('_',' ',(string)($definition['floating_eligible_role']??''))):((string)($definition['assigned_name']??'')?:'All eligible packers'); ?>
    <tr<?= !empty($definition['needs_attention'])?' class="needs-attention"':'' ?>><td><strong><?= htmlspecialchars((string)$definition['task_name'],ENT_QUOTES,'UTF-8') ?></strong><?php if(!empty($definition['needs_attention'])):?><small><i data-lucide="triangle-alert"></i>Needs attention<?= ($definition['assigned_employee_status']??'')!=='active'&&!empty($definition['assigned_employee_id'])?' · assigned employee inactive':'' ?></small><?php endif;?></td><td><?= htmlspecialchars($assignment,ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars(checklist_recurrence_label((string)$definition['recurring_rule']),ENT_QUOTES,'UTF-8') ?> · <?= htmlspecialchars(substr((string)$definition['due_time'],0,5),ENT_QUOTES,'UTF-8') ?></td><td><?= !empty($definition['next_run_at'])?htmlspecialchars(date('d M Y · H:i',strtotime((string)$definition['next_run_at'])),ENT_QUOTES,'UTF-8'):'—' ?></td><td><?= !empty($definition['last_run_at'])?htmlspecialchars(date('d M Y · H:i',strtotime((string)$definition['last_run_at'])),ENT_QUOTES,'UTF-8'):(!empty($definition['generated_last_at'])?htmlspecialchars(date('d M Y · H:i',strtotime((string)$definition['generated_last_at'])),ENT_QUOTES,'UTF-8'):'Never') ?></td><td><span class="recurring-status recurring-status--<?= htmlspecialchars($status,ENT_QUOTES,'UTF-8') ?>"><?= ucfirst($status) ?></span></td><td><button type="button" class="recurring-generated-link" data-recurring-occurrences="<?= $id ?>"><?= number_format((int)$definition['generated_count']) ?> tasks</button></td><td><div class="recurring-actions"><button type="button" data-recurring-edit="<?= $id ?>">Edit</button><?php if($status==='active'):?><form method="post" data-confirm="Pause this recurring task? Future occurrences will not be generated until it is resumed."><input type="hidden" name="action" value="recurring_pause"><input type="hidden" name="recurring_template_id" value="<?= $id ?>"><button type="submit">Pause</button></form><?php elseif($status==='paused'):?><form method="post"><input type="hidden" name="action" value="recurring_resume"><input type="hidden" name="recurring_template_id" value="<?= $id ?>"><button type="submit">Resume</button></form><?php endif;?><?php if(!in_array($status,['ended','cancelled'],true)):?><form method="post" data-confirm="End this recurrence permanently? Historical generated tasks will remain."><input type="hidden" name="action" value="recurring_end"><input type="hidden" name="recurring_template_id" value="<?= $id ?>"><button type="submit" class="is-caution">End</button></form><?php endif;?></div></td></tr>
    <tr class="recurring-occurrences-row" data-recurring-occurrences-row="<?= $id ?>" hidden><td colspan="8"><div data-recurring-occurrences-content>Loading generated tasks…</div></td></tr>
  <?php endforeach; ?></tbody></table></div>
  <?php foreach($recurringDefinitions as $definition): $id=(int)$definition['id']; $savedRule=(string)$definition['recurring_rule']; $savedDays=[]; if(preg_match('/^weekly_days:([1-7](?:,[1-7])*)$/',$savedRule,$savedMatch))$savedDays=array_map('intval',explode(',',$savedMatch[1])); ?><dialog class="recurring-edit-dialog" data-recurring-edit-dialog="<?= $id ?>"><form method="post"><header><div><span>Future occurrences only</span><h3>Edit Recurring Task</h3></div><button type="button" data-recurring-edit-close aria-label="Close">×</button></header><input type="hidden" name="action" value="recurring_update"><input type="hidden" name="recurring_template_id" value="<?= $id ?>"><input type="hidden" name="version_no" value="<?= (int)($definition['version_no']??1) ?>"><label><span>Task name</span><input name="task_name" value="<?= htmlspecialchars((string)$definition['task_name'],ENT_QUOTES,'UTF-8') ?>" required></label><label><span>Instructions</span><textarea name="instructions" required><?= htmlspecialchars((string)$definition['instructions'],ENT_QUOTES,'UTF-8') ?></textarea></label><div class="recurring-edit-grid"><label><span>Priority</span><select name="priority"><?php foreach($priorities as $value=>$label):?><option value="<?= $value ?>"<?= (string)$definition['priority']===$value?' selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label><label><span>Frequency</span><select name="recurring_rule"><option value="daily_business_day"<?= $savedRule==='daily_business_day'?' selected':'' ?>>Every business day</option><option value="weekly_days"<?= $savedDays?' selected':'' ?>>Weekly on selected days</option><?php foreach(['twice_weekly','weekly_1','weekly_2','weekly_3','weekly_4','weekly_5','weekly_saturday'] as $value):?><option value="<?= $value ?>"<?= $savedRule===$value?' selected':'' ?>><?= htmlspecialchars(checklist_recurrence_label($value),ENT_QUOTES,'UTF-8') ?></option><?php endforeach;?></select></label><fieldset class="task-repeat-weekdays"><legend>Repeat on</legend><?php foreach([1=>'Mon',2=>'Tue',3=>'Wed',4=>'Thu',5=>'Fri',6=>'Sat',7=>'Sun'] as $day=>$label):?><label><input type="checkbox" name="repeat_weekdays[]" value="<?=$day?>"<?=in_array($day,$savedDays,true)?' checked':''?>><span><?=$label?></span></label><?php endforeach;?></fieldset><label><span>Repeat time</span><input type="time" name="due_time" value="<?= htmlspecialchars(substr((string)$definition['due_time'],0,5),ENT_QUOTES,'UTF-8') ?>" required></label><label><span>Start date</span><input type="date" name="start_date" value="<?= htmlspecialchars((string)($definition['start_date']??''),ENT_QUOTES,'UTF-8') ?>"></label><label><span>End date</span><input type="date" name="end_date" value="<?= htmlspecialchars((string)($definition['end_date']??''),ENT_QUOTES,'UTF-8') ?>"></label></div><p>Changes apply to future generated occurrences only. Completed and already-generated task history is not rewritten.</p><footer><button type="button" data-recurring-edit-close>Cancel</button><button type="submit">Save Future Rule</button></footer></form></dialog><?php endforeach; ?>
</section>
